// =====================================================================================================================
// ★ Shenzhen Library and ★ Shenzhen Concert Hall (Arata Isozaki, the Shenzhen Cultural Center; Concert Hall opened October 2007,
// 1 680 seats in a "canyon terrace" vineyard hall; the Library 2008). Two long blocks side by side on the west of the axis, each on
// its OSM footprint and parts: a dark stone wall slab along the west side (44 m), the main body (40 m), and on the east side a
// curved glass curtain wall (34 m) over a stone base, behind it the entrance halls' "golden trees" (four groups of tree-like steel
// columns, the "cultural forest", two in each building). The two are joined by a pedestrian platform. Heights = the OSM part heights.
// =====================================================================================================================
const CU = {
  dark:{c:'#3e4144', m:0, lc:'#ffd9a8', lk:0.35}, stone:{c:'#c3beb3', m:0, lc:'#ffdcb0', lk:0.5}, body:{c:'#bdb9b0', m:0, lc:'#ffe2bc', lk:0.45}, band:{c:'#7d8f98', m:1, fh:3.2, cw:2.4, lc:'#ffe6c4'},
  glass:{c:'#86a3b4', glow:'#ffdcae', gk:0.42, op:0.82}, mull:{c:'#d8dad7'}, roof:'#9c9e9c', edge:'#d9d8d2',
  gold:{c:'#c9a046', glow:'#ffc860', gk:0.55}, inner:{c:'#e2d6bf', glow:'#ffe2b0', gk:0.35},
  slab:{c:'#d4d2cb', m:0, lc:'#ffe2bc', lk:0.6}
};
// a tree column: trunk to yb, then branches fanning out to the roof underside at yt
function treeColumn(B, s, x, z, yb, yt, rad, n, rng){
  obox(B, s, x, z, 1, 0, 1.6, 1.6, 0, yb, true);
  for (let i = 0; i < n; i++){ const a = i/n*TAU + rng()*0.4, r = rad*(0.6 + 0.4*rng()), m = [x + Math.cos(a)*r*0.45, lerp(yb, yt, 0.55), z + Math.sin(a)*r*0.45];
    beam(B, s, [x, yb - 0.2, z], m, 0.45); beam(B, s, m, [x + Math.cos(a)*r, yt - 0.3, z + Math.sin(a + 0.25)*r*0.8], 0.3);
    beam(B, s, m, [x + Math.cos(a - 0.5)*r*0.8, yt - 0.3, z + Math.sin(a - 0.5)*r*0.8], 0.25); }
}
function culturalBuild(Dd, treeSpec, seed){
  const g = new THREE.Group(), B = Batch(); let rs = seed; const rng = () => { rs = (rs*16807) % 2147483647; return rs/2147483647; };
  for (const p of Dd.parts){
    const P = p.r, h = p.t, bb = bbox(P), w = Math.min(bb[2] - bb[0], bb[3] - bb[1]);
    if (h >= 44 && w < 12){                       // the stone wall slabs (west wall; the end fins)
      prism(B, CU.dark, P, -0.5, h, false, CU.roof);
      alongEdges(P, 9, (x, z, ux, uz, L) => { if (L > 30) obox(B, CU.edge, x, z, ux, uz, 0.5, 0.0, 0, 0); });
    } else if (h <= 34.5 && h > 31){              // the east curtain wall band: glass over a stone base, a thin roof slab
      prism(B, CU.stone, P, -0.5, 6.6, true);
      // only the outer (east) edges get the curved glass; the inner straight edge meets the body
      curtain(B, P, 6.6, h - 1.0, CU, 3.0, 6.0, 0.35, 0.2);
      prism(B, CU.slab, grow(P, 0.8), h - 1.0, h, false);
      cap(B, CU.inner, P, 6.65);
      // the tree columns along the band
      const xs = P.map(q => q[0]), zs = P.map(q => q[1]); const cx = (Math.min(...xs) + Math.max(...xs))/2, z0 = Math.min(...zs), z1 = Math.max(...zs);
      if (z1 - z0 > 40) for (let k = 0; k < 2; k++){ const z = lerp(z0 + 26, z1 - 26, k); treeColumn(B, treeSpec, cx - 2.5, z, 17, h - 1.0, 12, 6, rng); }
    } else if (h <= 31){
      prism(B, CU.stone, P, -0.5, h, false, CU.roof);
    } else {                                      // the main body (40 m): stone grid with window bands, flat roof with a parapet
      prism(B, CU.body, P, -0.5, h - 1.6, true);
      for (let y = 7.0; y < h - 3; y += 9.6){ prism(B, CU.stone, grow(P, 0.25), y, y + 1.0, true); prism(B, CU.band, grow(P, 0.12), y + 1.0, y + 3.4, true); }
      prism(B, CU.stone, grow(P, 0.35), h - 1.6, h, true); cap(B, CU.roof, P, h - 0.4);
    }
  }
  B.flush(g); return g;
}
