LANDMARKS.szconcerthall = {zh:'深圳音乐厅', en:'Shenzhen Concert Hall', cat:'new', r:76, h:44, lt:{m:1, c:'#ffe2b0', k:0.7}, build(){ return culturalBuild(D.ch, CU.gold, 29); }};
