  const sk = []; for (let i = 0; i < 26; i++){ const a = i/26*TAU; sk.push([-12 + Math.cos(a)*42 + Math.cos(2*a)*6, 4 + Math.sin(a)*56 + Math.sin(3*a)*5]); }
