      for (let k = 0; k < 24; k++) for (let i = 0; i < 6; i++){ const a0 = k/24*TAU, a1 = (k + 1)/24*TAU, t0 = i/6*HP, t1 = (i + 1)/6*HP; B.q(CP.dome, Q(a0, t0), Q(a1, t0), Q(a1, t1), Q(a0, t1)); }
