  for (const p of D.bc.parts){ const P = p.r, bb = bbox(P);
    if (p.b > 1){ prism(B, BC.band, P, p.b, p.b + 1.2, false); curtain(B, P, p.b + 1.2, p.t - 1, BC, 3.0, 0, 0.3, 0.2); prism(B, BC.band, grow(P, 0.3), p.t - 1, p.t, false, BC.roof); continue; }
    curtain(B, grow(P, -0.2), -0.5, p.t - 1.2, BC, 3.4, 4.9, 0.35, 0.25);
    prism(B, BC.band, grow(P, 0.4), p.t - 1.2, p.t, true); cap(B, BC.roof, P, p.t - 0.2);
    // planted roof terraces: beds in a grid away from the spine
    const cx = (bb[0] + bb[2])/2;
    for (let z = bb[1] + 10; z < bb[3] - 10; z += 14) for (const dx of [-28, -16, 16, 28]){ const x = cx + dx; if (!pip(P, x, z)) continue; abox(B, BC.green, x - 4, z - 4, x + 4, z + 4, p.t - 0.2, p.t + 0.6); }
  }
  // the long glazed spine (a pitched skylight along the middle of the mall) with its ribs
  const sp = [[-3, -183], [-3, -45], [0, 0], [3, 45], [3, 166]];
  for (const [za, zb] of [[-182, -44], [-1, 166]]){ const x0 = za < 0 ? -3 : 3, W = 9, n = Math.round((zb - za)/6);
    for (let k = 0; k < n; k++){ const z0 = za + (zb - za)*k/n, z1 = za + (zb - za)*(k + 1)/n;
      B.q(BC.sky, [x0 - W, 10, z0], [x0 - W, 10, z1], [x0, 13.5, z1], [x0, 13.5, z0]); B.q(BC.sky, [x0, 13.5, z0], [x0, 13.5, z1], [x0 + W, 10, z1], [x0 + W, 10, z0]);
      beam(B, BC.rib, [x0 - W, 10.1, z0], [x0, 13.6, z0], 0.2); beam(B, BC.rib, [x0, 13.6, z0], [x0 + W, 10.1, z0], 0.2); }
    beam(B, BC.rib, [x0, 13.6, za], [x0, 13.6, zb], 0.3); }
