// =====================================================================================================================
const FT = {glass:{c:'#7c9aab', m:1, fh:6.6, cw:3.2, lc:'#e9f2ff'}, mull:{c:'#d5d8d8'}, steel:{c:'#e6e8e7', m:0, lc:'#eef4ff', lk:0.6, e:0.8},
  roof:{c:'#bfc5c8', m:0, lc:'#eef4ff', lk:0.3}, stone:'#c6c1b6', bglass:{c:'#9db4c0', glow:'#dce8f2', gk:0.32, op:0.72}, lamp:{c:'#f4ead2', glow:'#fff1d0', gk:1.6}};
const FTH = 26;
LANDMARKS.szfutianport = {zh:'福田口岸', en:'Futian Port', cat:'new', r:120, h:FTH + 4, lt:{m:1, c:'#e6efff', k:0.65}, build(){
  const g = new THREE.Group(), B = Batch(), R = D.ft.ring;
  // long axis of the hall (the OSM rectangle)
  const ux = R[1][0] - R[0][0], uz = R[1][1] - R[0][1], L = Math.hypot(ux, uz), u = [ux/L, uz/L], v = [-u[1], u[0]], W = Math.hypot(R[3][0] - R[0][0], R[3][1] - R[0][1]);
  const cx = (R[0][0] + R[2][0])/2, cz = (R[0][1] + R[2][1])/2, Pt = (a, b) => [cx + u[0]*a + v[0]*b, cz + u[1]*a + v[1]*b];
  prism(B, FT.stone, R, -0.5, 1.2, true);
  curtain(B, grow(R, -0.6), 1.2, FTH - 2, FT, 3.2, 6.6, 0.5, 0.35);
  // the roof: a shallow barrel over the hall, overhanging 4 m, on a steel edge beam
  const nA = 30, nB = 10, hw = W/2 + 4, hl = L/2 + 4, yR = (b) => FTH - 2 + 4.0*(1 - (b/hw)**2);
  for (let i = 0; i < nA; i++) for (let j = 0; j < nB; j++){ const a0 = -hl + 2*hl*i/nA, a1 = -hl + 2*hl*(i + 1)/nA, b0 = -hw + 2*hw*j/nB, b1 = -hw + 2*hw*(j + 1)/nB;
    const p = (a, b) => { const q = Pt(a, b); return [q[0], yR(b), q[1]]; }; B.q(FT.roof, p(a0, b0), p(a0, b1), p(a1, b1), p(a1, b0)); }
  for (const sb of [-1, 1]){ for (let i = 0; i < nA; i++){ const a0 = -hl + 2*hl*i/nA, a1 = -hl + 2*hl*(i + 1)/nA, q0 = Pt(a0, sb*hw), q1 = Pt(a1, sb*hw);
      B.q(FT.steel, [q0[0], FTH - 3.2, q0[1]], [q1[0], FTH - 3.2, q1[1]], [q1[0], FTH - 2, q1[1]], [q0[0], FTH - 2, q0[1]]); }
    for (let a = -hl + 6; a < hl; a += 12){ const q = Pt(a, sb*(W/2 + 2.5)); obox(B, FT.steel, q[0], q[1], u[0], u[1], 0.9, 0.9, 0, FTH - 3, true); } }
  B.flush(g); return g; }};
LANDMARKS.szfutianport_b = {zh:'福田口岸', en:'Futian Port', cat:'new', r:160, h:26, label:false, lt:{m:1, c:'#e6efff', k:0.6}, build(){
  const g = new THREE.Group(), B = Batch(), F = D.ftb;
  // the axis between the two decks (upper from (68.0, 39.5), lower from (69.7, 39.3)), in this key's frame (anchored at its middle)
  const a = [(F.lo[1][0] + F.up[0][0])/2, (F.lo[1][1] + F.up[0][1])/2], b = [(F.lo[0][0] + F.up[1][0])/2, (F.lo[0][1] + F.up[1][1])/2];
  const m = [(a[0] + b[0])/2, (a[1] + b[1])/2], A = [a[0] - m[0], a[1] - m[1]], Bp = [b[0] - m[0], b[1] - m[1]];
  const L = Math.hypot(Bp[0] - A[0], Bp[1] - A[1]), u = [(Bp[0] - A[0])/L, (Bp[1] - A[1])/L], v = [-u[1], u[0]], hw = 8.25;
  const P = (s, t) => [A[0] + u[0]*s + v[0]*t, A[1] + u[1]*s + v[1]*t], y0 = F.ylo - 1.9, y1 = F.yup + 4.6;
  // bottom chord / soffit, the glazed sides, the roof, the truss posts and diagonals, the deck lights
  const q = (s0, s1, t, ya, yb, sp) => { const p0 = P(s0, t), p1 = P(s1, t); B.q(sp, [p0[0], ya, p0[1]], [p1[0], ya, p1[1]], [p1[0], yb, p1[1]], [p0[0], yb, p0[1]]); };
  for (let s = 0; s < L - 0.1; s += 8){ const s1 = Math.min(L, s + 8);
    for (const t of [-hw, hw]){ q(s, s1, t, y0, y0 + 1.4, FT.steel); q(s, s1, t, y0 + 1.4, y1 - 1.2, FT.bglass); q(s, s1, t, y1 - 1.2, y1, FT.steel); q(s, s1, t, F.ylo + 4.2, F.ylo + 5.0, FT.steel); }
    const c = [P(s, -hw), P(s1, -hw), P(s1, hw), P(s, hw)];
    B.q(FT.steel, [c[0][0], y0, c[0][1]], [c[3][0], y0, c[3][1]], [c[2][0], y0, c[2][1]], [c[1][0], y0, c[1][1]]);
    B.q(FT.roof, [c[0][0], y1, c[0][1]], [c[1][0], y1, c[1][1]], [P(s1, 0)[0], y1 + 1.2, P(s1, 0)[1]], [P(s, 0)[0], y1 + 1.2, P(s, 0)[1]]);
    B.q(FT.roof, [P(s, 0)[0], y1 + 1.2, P(s, 0)[1]], [P(s1, 0)[0], y1 + 1.2, P(s1, 0)[1]], [c[2][0], y1, c[2][1]], [c[3][0], y1, c[3][1]]);
    for (const t of [-hw - 0.3, hw + 0.3]){ const p0 = P(s, t), p1 = P(s1, t); beam(B, FT.steel, [p0[0], y0 + 1.4, p0[1]], [p0[0], y1 - 1.2, p0[1]], 0.25); beam(B, FT.steel, [p0[0], y0 + 1.4, p0[1]], [p1[0], y1 - 1.2, p1[1]], 0.18); }
    const pl = P(s + 4, 0); lampBox(B, FT.lamp, pl[0], y1 - 0.4, pl[1], 0.6); }
  // piers every ~40 m (paired columns under the soffit) down to the river bed / bank
  for (let s = 20; s < L; s += 42) for (const t of [-5, 5]){ const p = P(s, t); obox(B, FT.steel, p[0], p[1], u[0], u[1], 1.6, 1.6, -4, y0, true); }
  B.flush(g); return g; }};
place('szfutianport');
