  const WAT = polyIdx(S.water), LAWN = polyIdx(S.lawn), PLZ = polyIdx(S.plaza), BLD = polyIdx(S.bld.map(b => grow(b.r, 3))), GRN = polyIdx(S.green);
  const bad = (x, z) => inAny(WAT, x, z, 3) || inAny(PLZ, x, z, 2) || inAny(BLD, x, z) || pd(x, z) < 2.5;
  scatter(ctx, S.green, 11, (x, z) => ctx.tree(x, z, 3.0 + ctx.rng()*2.4, ctx.rng() < 0.6 ? 'raintree' : 'd'), bad);
  scatter(ctx, all, 16, (x, z) => ctx.tree(x, z, 3.2 + ctx.rng()*2.2, ctx.rng() < 0.15 ? 'palm' : ctx.rng() < 0.6 ? 'raintree' : 'd'), (x, z) => bad(x, z) || inAny(LAWN, x, z, -4) || inAny(GRN, x, z));
  // rows of trees along the river banks
